export function songUsage(reader){const names=new Map();for(const map of reader?.maps||[]){const id=reader.u16(map.address+16),rows=names.get(id)||[];const name=map.label||map.key;if(!rows.includes(name))rows.push(name);names.set(id,rows);}return names;}
export function describeSong(bytes,table,id,{hash='',usage=new Map()}={}){
 const v=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength),at=table+id*8,h=v.getUint32(at,true)-0x08000000,count=bytes[h]||0,maps=usage.get(id)||[];
 const known=hash===STOCK&&table===4862668?FIRE_RED[id]:null,kind=!count?'empty':known?.kind||(v.getUint16(at+4,true)===0?'music':'effect');
 const name=known?.name||(maps.length?maps.slice(0,2).join(' / '):kind==='empty'?'Silent cue #'+id:kind==='effect'?'Sound effect #'+id:'Theme #'+id+' · '+count+' parts');
 return{id,name,kind,count,maps};
}
export function improvedLibraryName(track){
 if(!/^Track\s+\d+$/i.test(track.name))return null;const a=track.asset,id=a?.sourceSongId;if(!Number.isInteger(id))return null;
 return a.sourceHash===STOCK&&a.sourceTable===4862668&&FIRE_RED[id]?FIRE_RED[id].name:'ROM cue #'+id+' · '+a.trackCount+' parts';
}
